def saisie():
    global N
    valide=False
    while valide==False:
        N=int(input("Entrer le nombre d'éléments :"))
        valide=5<=N<=20
def remplir():
    global T
    T=[0]*20
    for i in range(N):
        T[i]=int(input('Nombre '+str(i+1)+' :'))
def tri_selection (T,N):
    for i in range(N-1):
        posmin=i
        for j in range(i+1,N):
            if T[j]<T[posmin]:
                posmin=j
        if posmin!=i:
            aux=T[i]
            T[i]=T[posmin]
            T[posmin]=aux
def affiche(T,N):
    print("*** aprés le tri***" )
    for i in range (N):
        print(T[i])

######### PP ###########
saisie()
remplir()
tri_selection(T,N)
affiche(T,N)
